-- Initial 25 candidate claims, 0 approvals, 0 rights grants. Fails if article slugs/versions moved.
DO $kdb_evidence_seed$
DECLARE v_owner uuid; d jsonb; a public.gu_knowledge_articles_v1%ROWTYPE;
 v_claim public.gu_knowledge_claim_evidence_v1%ROWTYPE; v_count integer:=0; n integer;
BEGIN
 SELECT r.user_id INTO v_owner FROM public.admin_user_roles r JOIN public.profiles p ON p.id=r.user_id
 WHERE r.role_code='OWNER' AND (r.expires_at IS NULL OR r.expires_at>now())
 AND p.account_kind='member' AND p.deleted_at IS NULL
 AND NOT EXISTS(SELECT 1 FROM public.admin_user_flags f WHERE f.user_id=r.user_id AND f.status IN ('restricted','suspended'))
 ORDER BY r.user_id LIMIT 1;
 IF v_owner IS NULL THEN RAISE EXCEPTION 'Active Owner required'; END IF;
 SELECT count(*) INTO n FROM public.gu_knowledge_claim_evidence_v1 WHERE claim_key LIKE 'P25-%';
 IF n<>0 THEN RAISE EXCEPTION 'Priority 25 claim keys already exist; refuse double seeding'; END IF;
 FOR d IN SELECT value FROM jsonb_array_elements('[{"claim_key":"P25-01","slug":"research-study-sma","article_version":12,"claim_text":"A three-bar SMA uses exactly three declared completed closing prices.","claim_type":"numeric","source_url":"https://chartschool.stockcharts.com/table-of-contents/technical-indicators-and-overlays/technical-overlays","source_title":"Indicator reference 1","proposed_competency":"CHART_STRUCTURE"},{"claim_key":"P25-02","slug":"research-study-vwap","article_version":11,"claim_text":"Exact transaction VWAP weights eligible trade prices by share size, divided by total eligible shares.","claim_type":"numeric","source_url":"https://toslc.thinkorswim.com/center/reference/Tech-Indicators/studies-library/V-Z/VWAP","source_title":"Approved research candidate 1","proposed_competency":"VWAP_CONTEXT"},{"claim_key":"P25-03","slug":"knowledge-b003-trade-vwap-vs-proxy","article_version":3,"claim_text":"HLC3 bar-based VWAP is a proxy and need not equal exact transaction VWAP.","claim_type":"numeric","source_url":"https://toslc.thinkorswim.com/center/reference/Tech-Indicators/studies-library/V-Z/VWAP","source_title":"thinkorswim VWAP methodology","proposed_competency":"VWAP_CONTEXT"},{"claim_key":"P25-04","slug":"knowledge-b003-ema-seed-convergence","article_version":3,"claim_text":"EMA warmup and seed choice can alter calculated early study values.","claim_type":"numeric","source_url":"https://toslc.thinkorswim.com/center/reference/Tech-Indicators/studies-library/M-N/MovAvgExponential","source_title":"thinkorswim EMA methodology","proposed_competency":"EMA_CONTEXT"},{"claim_key":"P25-05","slug":"research-study-bollinger-bands","article_version":8,"claim_text":"Bollinger-style bands require a declared average, volatility convention and multiplier.","claim_type":"numeric","source_url":"https://chartschool.stockcharts.com/table-of-contents/technical-indicators-and-overlays/technical-overlays/bollinger-bands","source_title":"Approved research candidate 1","proposed_competency":"CHART_STRUCTURE"},{"claim_key":"P25-06","slug":"knowledge-b003-volatility-bands-sigma-choice","article_version":3,"claim_text":"Sample and population standard deviations give different values on the same finite sample.","claim_type":"numeric","source_url":"https://ta-lib.org/functions/","source_title":"TA-Lib documented functions","proposed_competency":"CHART_STRUCTURE"},{"claim_key":"P25-07","slug":"research-study-macd-histogram","article_version":8,"claim_text":"A MACD histogram requires a specified MACD line minus signal line convention.","claim_type":"numeric","source_url":"https://chartschool.stockcharts.com/table-of-contents/technical-indicators-and-overlays/technical-indicators","source_title":"Approved research candidate 1","proposed_competency":"EMA_CONTEXT"},{"claim_key":"P25-08","slug":"research-study-vix-context","article_version":8,"claim_text":"VIX is options-based volatility context and is not a directional stock-price forecast.","claim_type":"methodology","source_url":"https://www.cboe.com/insights/posts/what-the-vix-and-vix-1-d-indices-attempt-to-measure-and-how-they-differ","source_title":"Approved research candidate 1","proposed_competency":"MARKET_REGIME"},{"claim_key":"P25-09","slug":"research-study-stoch-rsi","article_version":8,"claim_text":"Stochastic RSI normalizes an RSI series rather than the underlying closing-price series.","claim_type":"numeric","source_url":"https://chartschool.stockcharts.com/table-of-contents/technical-indicators-and-overlays/technical-indicators","source_title":"Approved research candidate 1","proposed_competency":"CHART_STRUCTURE"},{"claim_key":"P25-10","slug":"research-study-anchored-vwap","article_version":8,"claim_text":"Anchored VWAP depends on its explicit start time or event and underlying trade/bar data scope.","claim_type":"numeric","source_url":"https://chartschool.stockcharts.com/table-of-contents/technical-indicators-and-overlays/technical-overlays/anchored-vwap","source_title":"Approved research candidate 1","proposed_competency":"VWAP_CONTEXT"},{"claim_key":"P25-11","slug":"knowledge-b003-margin-interest-and-maintenance","article_version":3,"claim_text":"Margin borrowing interest and maintenance margin are distinct account obligations.","claim_type":"regulatory","source_url":"https://www.finra.org/investors","source_title":"FINRA Investor Education","proposed_competency":"POSITION_SIZING"},{"claim_key":"P25-12","slug":"watchlist-stories-03-day-trading-morning-preparation","article_version":1,"claim_text":"The June 2026 FINRA intraday margin transition requires broker-specific checks during permitted firm transition.","claim_type":"regulatory","source_url":"https://syndication.finra.org/content/understanding-new-intraday-margin-requirements","source_title":"FINRA — Understanding New Intraday Margin Requirements","proposed_competency":"ORDER_SELECTION"},{"claim_key":"P25-13","slug":"knowledge-b003-clearing-netting-settlement","article_version":3,"claim_text":"Trade execution, clearing, netting, and settlement are distinct post-trade processes.","claim_type":"regulatory","source_url":"https://www.dtcc.com/","source_title":"DTCC clearing and settlement","proposed_competency":"ORDER_SELECTION"},{"claim_key":"P25-14","slug":"knowledge-b003-options-assignment-obligation","article_version":3,"claim_text":"Long-option exercise rights differ from short-option assignment obligations.","claim_type":"derivatives","source_url":"https://www.nfa.futures.org/investors/","source_title":"NFA Investor Education","proposed_competency":null},{"claim_key":"P25-15","slug":"knowledge-b003-futures-tick-margin","article_version":3,"claim_text":"Futures tick monetary value and the performance bond are different contract concepts.","claim_type":"derivatives","source_url":"https://www.cmegroup.com/education.html","source_title":"CME Education","proposed_competency":null},{"claim_key":"P25-16","slug":"knowledge-b003-greeks-local-approximation","article_version":3,"claim_text":"Option Greeks describe local sensitivities, not guaranteed exact price changes.","claim_type":"derivatives","source_url":"https://www.cboe.com/optionsinstitute/","source_title":"Cboe Options Institute","proposed_competency":null},{"claim_key":"P25-17","slug":"knowledge-b002-stop-order-trigger-versus-fill","article_version":3,"claim_text":"A stop trigger does not guarantee a particular fill price.","claim_type":"regulatory","source_url":"https://www.investor.gov/introduction-investing/investing-basics/how-stock-markets-work/types-orders","source_title":"SEC Investor.gov types of orders","proposed_competency":"ORDER_SELECTION"},{"claim_key":"P25-18","slug":"knowledge-b002-market-order-with-depth","article_version":3,"claim_text":"A sufficiently large market order may execute at multiple available price levels.","claim_type":"microstructure","source_url":"https://www.investor.gov/introduction-investing/investing-basics/how-stock-markets-work/types-orders","source_title":"SEC Investor.gov types of orders","proposed_competency":"SLIPPAGE_SPREAD"},{"claim_key":"P25-19","slug":"knowledge-b002-buy-and-sell-limit-orders","article_version":3,"claim_text":"A limit order constrains price but does not guarantee execution.","claim_type":"regulatory","source_url":"https://www.investor.gov/introduction-investing/investing-basics/how-stock-markets-work/types-orders","source_title":"SEC Investor.gov types of orders","proposed_competency":"ORDER_SELECTION"},{"claim_key":"P25-20","slug":"knowledge-b003-trades-quotes-depth-distinction","article_version":3,"claim_text":"Completed trades, resting quotes and depth are different observational datasets.","claim_type":"microstructure","source_url":"https://www.sec.gov/marketstructure","source_title":"SEC Market Structure","proposed_competency":"TAPE_READING"},{"claim_key":"P25-21","slug":"knowledge-b003-order-book-depth-changes","article_version":3,"claim_text":"Displayed order-book quantity can change or cancel without any execution.","claim_type":"microstructure","source_url":"https://www.nasdaqtrader.com/","source_title":"Nasdaq Trader","proposed_competency":"LEVEL2_READING"},{"claim_key":"P25-22","slug":"knowledge-b003-market-by-order-vs-level","article_version":3,"claim_text":"Market-by-order data differ from price-level aggregated depth views.","claim_type":"microstructure","source_url":"https://lobsterdata.com/","source_title":"LOBSTER order-book samples","proposed_competency":"LEVEL2_READING"},{"claim_key":"P25-23","slug":"knowledge-b003-auction-indicative-vs-executed","article_version":3,"claim_text":"Auction indicative prices can differ from prices of final executed auction prints.","claim_type":"microstructure","source_url":"https://www.nyse.com/market-data","source_title":"NYSE Market Data","proposed_competency":"TAPE_READING"},{"claim_key":"P25-24","slug":"knowledge-b003-nyse-exchange-depth-rights","article_version":3,"claim_text":"Public feed specifications do not automatically grant redistribution rights for exchange depth data.","claim_type":"rights","source_url":"https://www.nyse.com/data-products/","source_title":"NYSE exchange data products","proposed_competency":"LEVEL2_READING"},{"claim_key":"P25-25","slug":"knowledge-b003-fred-series-specific-rights","article_version":3,"claim_text":"FRED series may have third-party content rights and restrictions separate from general site access.","claim_type":"rights","source_url":"https://fred.stlouisfed.org/legal/","source_title":"FRED license/rights policy","proposed_competency":null}]'::jsonb) LOOP
 SELECT * INTO STRICT a FROM public.gu_knowledge_articles_v1
 WHERE slug=d->>'slug' AND version=(d->>'article_version')::integer AND status='published' AND is_visible;
 INSERT INTO public.gu_knowledge_claim_evidence_v1
  (article_id,article_version,claim_key,claim_text,claim_type,source_url,source_title,
   proposed_competency,created_by,updated_by,verification_state,source_coverage,rights_status)
 VALUES(a.id,a.version,d->>'claim_key',d->>'claim_text',d->>'claim_type',
        d->>'source_url',d->>'source_title',d->>'proposed_competency',v_owner,v_owner,
        'candidate','candidate','not_cleared') RETURNING * INTO v_claim;
 INSERT INTO public.gu_knowledge_claim_evidence_events_v1
  (claim_id,claim_revision,action,snapshot,actor_user_id)
 VALUES(v_claim.id,v_claim.revision,'candidate_created',to_jsonb(v_claim),v_owner);
 v_count:=v_count+1;
 END LOOP;
 IF v_count<>25 THEN RAISE EXCEPTION 'Expected 25 unique priority claims, got %',v_count;END IF;
 INSERT INTO public.admin_audit_log(actor_user_id,action,target_type,target_id,details)
 VALUES(v_owner,'knowledge.claim_evidence_25_seeded_v1','knowledge_claim_batch','SMFGU-KDB-CLAIM-EVIDENCE-025',
 jsonb_build_object('count',v_count,'source_review','candidate_not_verified','rights_clearance',false,
 'independent_professional_approval',false,'article_membership_changed',false));
END $kdb_evidence_seed$;